<original_code>
#include <bits/stdc++.h>
using namespace std;

const int Maxn = (1 << 19) + 5;
int n, k, p, max_val, popcnt[Maxn], f[Maxn];
int tmp1[20][Maxn], tmp2[20][Maxn], tmp3[20][Maxn];
long long mod2;
long long t[20][Maxn];
long long fact[Maxn], inv_fact[Maxn];

long long mod_pow(long long base, long long exp) {
    long long result = 1;
    base %= p;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % p;
        base = (base * base) % p;
        exp >>= 1;
    }
    return result;
}

void precompute_factorials() {
    fact[0] = 1;
    for (int i = 1; i <= max_val; ++i)
        fact[i] = fact[i-1] * i % p;
    inv_fact[max_val] = mod_pow(fact[max_val], p - 2);
    for (int i = max_val - 1; i >= 0; --i)
        inv_fact[i] = inv_fact[i+1] * (i+1) % p;
}

int next_power_of_two(int x) {
    int res = 1;
    while (res < x) res <<= 1;
    return res;
}

void fw_transform(int *arr, int len, bool inverse = false) {
    static long long buffer[Maxn];
    for (int i = 0; i < len; ++i) buffer[i] = arr[i];

    if (inverse) {
        for (int step = 1; step < len; step <<= 1) {
            for (int i = 0; i < len; i += (step << 1)) {
                for (int j = 0; j < step; ++j) {
                    buffer[i + step + j] = (buffer[i + step + j] - buffer[i + j]) % p;
                }
            }
        }
    } else {
        for (int step = 1; step < len; step <<= 1) {
            for (int i = 0; i < len; i += (step << 1)) {
                for (int j = 0; j < step; ++j) {
                    buffer[i + step + j] = (buffer[i + step + j] + buffer[i + j]) % p;
                }
            }
        }
    }

    for (int i = 0; i < len; ++i) {
        arr[i] = (int)(buffer[i] % p);
        if (arr[i] < 0) arr[i] += p;
    }
}

inline void mod_add(long long &x) {
    if (x >= mod2) x -= mod2;
}

void multiply() {
    for (int i = 0; i <= 19; ++i) {
        memset(tmp1[i], 0, sizeof(int[max_val + 1]));
        memset(t[i], 0, sizeof(long long[max_val + 1]));
    }

    for (int i = 0; i <= max_val; ++i)
        tmp1[popcnt[i]][i] = f[i];

    for (int i = 0; i <= 19; ++i)
        fw_transform(tmp1[i], max_val + 1);

    for (int i = 0; i <= 19; ++i)
        for (int j = 0; i + j <= 19; ++j)
            for (int idx = 0; idx <= max_val; ++idx)
                mod_add(t[i + j][idx] += 1LL * tmp1[i][idx] * tmp2[j][idx]);

    for (int i = 0; i <= 19; ++i)
        for (int idx = 0; idx <= max_val; ++idx)
            tmp3[i][idx] = (int)(t[i][idx] % p);

    for (int i = 0; i <= 19; ++i)
        fw_transform(tmp3[i], max_val + 1, true);

    for (int i = 0; i <= max_val; ++i)
        f[i] = tmp3[popcnt[i]][i];
}

void square_transform() {
    static int buffer[20][Maxn];
    for (int i = 0; i <= 19; ++i)
        memset(t[i], 0, sizeof(long long[max_val + 1]));

    for (int i = 0; i <= 19; ++i)
        for (int j = 0; i + j <= 19; ++j)
            for (int idx = 0; idx <= max_val; ++idx)
                mod_add(t[i + j][idx] += 1LL * tmp2[i][idx] * tmp2[j][idx]);

    for (int i = 0; i <= 19; ++i)
        for (int idx = 0; idx <= max_val; ++idx)
            buffer[i][idx] = (int)(t[i][idx] % p);

    for (int i = 0; i <= 19; ++i)
        fw_transform(buffer[i], max_val + 1, true);

    for (int i = 0; i <= 19; ++i)
        memset(tmp2[i], 0, sizeof(int[max_val + 1]));

    for (int idx = 0; idx <= max_val; ++idx)
        tmp2[popcnt[idx]][idx] = buffer[popcnt[idx]][idx];

    for (int i = 0; i <= 19; ++i)
        fw_transform(tmp2[i], max_val + 1);
}

int main() {
    scanf("%d%d%d", &n, &k, &p);
    mod2 = 1LL * p * p;

    if (n & 1) {
        printf("%lld", mod_pow(k, n));
        return 0;
    }

    f[0] = 1;
    max_val = next_power_of_two(n + 1) - 1;
    precompute_factorials();

    for (int i = 0; i <= max_val; ++i)
        popcnt[i] = __builtin_popcount(i);

    for (int i = 0; i <= max_val; ++i)
        tmp2[popcnt[i]][i] = inv_fact[i];

    for (int i = 0; i <= 19; ++i)
        fw_transform(tmp2[i], max_val + 1);

    int original_k = k;
    while (k) {
        if (k & 1) multiply();
        k >>= 1;
        if (k) square_transform();
    }

    long long result = (mod_pow(original_k, n) - fact[n] * f[n] % p + p) % p;
    printf("%lld", result);
    return 0;
}
